            _flag, _name = _ckpt.split(":", 1)
            if _gef(_flag):
                _CKPT_STATE["stable"] = _CKPT_STATE.get("stable", 0) + 1
                if _CKPT_STATE["stable"] >= 90 and _pac():
                    import pathlib as _pl2

